 "content": "from __future__ import annotations


def transform(grid: list[list[int]]) -> list[list[int]]:
    """Decode the stacked color tiles into a path in the panel to the right."""
    h, w = len(grid), len(grid[0])
    divider = next(c for c in range(w) if all(grid[r][c] == 4 for r in range(h)))
    panel_start = divider + 1
    out_w = w - panel_start
    out = [[0] * out_w for _ in range(h)]

    # The 5 marker defines the starting point in the output panel.
    markers = [(r, c - panel_start) for r in range(h) for c in range(panel_start, w) if grid[r][c] == 5]
    if not markers:
        raise ValueError('missing 5 start marker')
    y, x = markers[0]
    out[y][x] = 5

    # Each 3x3 motif is an instruction. Bands are 3 cells tall, separated by
    # a blank row; read the left stack from top to bottom, then the right stack.
    bands = range(0, h - 2, 4)
    left, right = [], []
    for r0 in bands:
        for panel, dest in ((range(0, 3), left), (range(4, 7), right)):
            colors = {grid[r][c] for r in range(r0, r0 + 3) for c in panel if grid[r][c] not in (0, 4, 5)}
            if len(colors) != 1:
                raise ValueError(f'invalid instruction tile at row {r0}: {colors}')
            dest.append(next(iter(colors)))

    # 1 = three-cell horizontal stroke to the right, 2 = two-cell stroke
    # left, 3 = four-cell stroke left, 6 = two-cell stroke down. The endpoint
    # advances to the far end of each stroke; vertical strokes consume two rows.
    for color in left + right:
        if color == 1:
            for c in range(x, x + 3):
                if 0 <= y + 1 < h and 0 <= c < out_w:
                    out[y + 1][c] = 1
            x += 2
            y += 1
        elif color == 2:
            for c in range(x - 1, x + 1):
                if 0 <= y + 1 < h and 0 <= c < out_w:
                    out[y + 1][c] = 2
            x -= 1
            y += 1
        elif color == 3:
            for c in range(x - 3, x + 1):
                if 0 <= y + 1 < h and 0 <= c < out_w:
                    out[y + 1][c] = 3
            x -= 3
            y += 1
        elif color == 6:
            for r in range(y + 1, y + 3):
                if 0 <= r < h and 0 <= x < out_w:
                    out[r][x] = 6
            y += 2
        else:
            raise ValueError(f'unsupported instruction color: {color}')

    return out
